{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2166-10-03 16:00:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be your doctor during this stay. Can you tell me what brought you in today?"
    },
    {
      "turn_number": 2,
      "time": "2166-10-03 16:02:00",
      "speaker": "Patient",
      "text": "Hi, thanks. I’ve had this cough with green mucus and pain when I swallow. It’s been getting worse, and I haven’t been eating much because it hurts."
    },
    {
      "turn_number": 3,
      "time": "2166-10-03 16:04:00",
      "speaker": "Doctor",
      "text": "I see. Any chills or fever?"
    },
    {
      "turn_number": 4,
      "time": "2166-10-03 16:05:00",
      "speaker": "Patient",
      "text": "Yeah, I had chills yesterday. No fever that I checked, but I felt shaky."
    },
    {
      "turn_number": 5,
      "time": "2166-10-03 16:07:00",
      "speaker": "Doctor",
      "text": "Okay. Given your history with the tracheostomy and airway issues, we want to make sure nothing serious is going on. We’ve ordered a chest X-ray and some blood work."
    },
    {
      "turn_number": 6,
      "time": "2166-10-03 16:09:00",
      "speaker": "Patient",
      "text": "Alright. I was here last month for throat pain too. Is this the same thing?"
    },
    {
      "turn_number": 7,
      "time": "2166-10-03 16:11:00",
      "speaker": "Doctor",
      "text": "It’s similar, but this time you have more cough and sputum. We’re checking to see if it’s an infection or just irritation from your airway."
    },
    {
      "turn_number": 8,
      "time": "2166-10-03 16:13:00",
      "speaker": "Patient",
      "text": "I also felt dizzy earlier. Do you think that’s from not eating?"
    },
    {
      "turn_number": 9,
      "time": "2166-10-03 16:15:00",
      "speaker": "Doctor",
      "text": "Very likely. Your blood pressure was a bit low, and since you’ve had poor intake, we think it’s due to mild dehydration. We’re starting IV fluids to help."
    },
    {
      "turn_number": 10,
      "time": "2166-10-03 16:17:00",
      "speaker": "Patient",
      "text": "That makes sense. The dizziness has gotten better since I got here."
    },
    {
      "turn_number": 11,
      "time": "2166-10-03 16:19:00",
      "speaker": "Doctor",
      "text": "Good. We’ll keep the fluids going for a few hours to make sure you’re well hydrated."
    },
    {
      "turn_number": 12,
      "time": "2166-10-03 17:30:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray came back. No pneumonia or other lung issues. That’s reassuring."
    },
    {
      "turn_number": 13,
      "time": "2166-10-03 17:32:00",
      "speaker": "Patient",
      "text": "That’s good to hear. So what’s causing the cough and pain?"
    },
    {
      "turn_number": 14,
      "time": "2166-10-03 17:34:00",
      "speaker": "Doctor",
      "text": "We think it’s viral bronchotracheitis—basically a viral irritation of your airway. ENT is coming to look at your trach site to confirm."
    },
    {
      "turn_number": 15,
      "time": "2166-10-03 17:36:00",
      "speaker": "Patient",
      "text": "Will they do a scope?"
    },
    {
      "turn_number": 16,
      "time": "2166-10-03 17:38:00",
      "speaker": "Doctor",
      "text": "Yes, a fiberoptic exam through your tracheostomy. It’s quick and helps us see if there’s any inflammation or infection."
    },
    {
      "turn_number": 17,
      "time": "2166-10-03 18:15:00",
      "speaker": "Doctor",
      "text": "The ENT team just finished. They didn’t see any signs of tracheitis or structural problems. No infection in the airway."
    },
    {
      "turn_number": 18,
      "time": "2166-10-03 18:17:00",
      "speaker": "Patient",
      "text": "So no antibiotics?"
    },
    {
      "turn_number": 19,
      "time": "2166-10-03 18:19:00",
      "speaker": "Doctor",
      "text": "Correct. Since it’s likely viral and no bacterial infection was found, antibiotics aren’t needed. We’ll focus on symptom control."
    },
    {
      "turn_number": 20,
      "time": "2166-10-03 18:21:00",
      "speaker": "Patient",
      "text": "Okay, that’s fine. My throat still hurts a lot when I swallow."
    },
    {
      "turn_number": 21,
      "time": "2166-10-03 18:23:00",
      "speaker": "Doctor",
      "text": "We’ll manage that with pain medication. You were on oxycodone at home—we’ll start with that and add ibuprofen and gabapentin if needed."
    },
    {
      "turn_number": 22,
      "time": "2166-10-04 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s the pain today?"
    },
    {
      "turn_number": 23,
      "time": "2166-10-04 09:02:00",
      "speaker": "Patient",
      "text": "Better, especially after the meds. I even had some soup last night."
    },
    {
      "turn_number": 24,
      "time": "2166-10-04 09:04:00",
      "speaker": "Doctor",
      "text": "That’s great. Your labs show mild anemia, but it’s consistent with your baseline. Nothing new there."
    },
    {
      "turn_number": 25,
      "time": "2166-10-04 09:06:00",
      "speaker": "Patient",
      "text": "I’ve had that for years. My hemoglobin is usually around 9 or 10."
    },
    {
      "turn_number": 26,
      "time": "2166-10-04 09:08:00",
      "speaker": "Doctor",
      "text": "Exactly. We’re not concerned about it now. We’re also continuing your omeprazole and ranitidine for reflux—it can make throat pain worse."
    },
    {
      "turn_number": 27,
      "time": "2166-10-04 10:30:00",
      "speaker": "Doctor",
      "text": "Speech and swallow therapy stopped by. They think you’re at your baseline for swallowing. Any choking episodes before coming in?"
    },
    {
      "turn_number": 28,
      "time": "2166-10-04 10:32:00",
      "speaker": "Patient",
      "text": "Yeah, I choked a little on some Fritos. I think I just ate too fast."
    },
    {
      "turn_number": 29,
      "time": "2166-10-04 10:34:00",
      "speaker": "Doctor",
      "text": "They recommend sticking to softer foods and taking your time. They’ll arrange a barium swallow test after discharge to check your swallowing more closely."
    },
    {
      "turn_number": 30,
      "time": "2166-10-04 10:36:00",
      "speaker": "Patient",
      "text": "Okay, I can do that. Should I avoid crunchy stuff?"
    },
    {
      "turn_number": 31,
      "time": "2166-10-04 10:38:00",
      "speaker": "Doctor",
      "text": "For now, yes. Stick to things like mashed potatoes, yogurt, or shakes. Nutrition also suggested Carnation supplements if you’re not eating enough."
    },
    {
      "turn_number": 32,
      "time": "2166-10-04 14:00:00",
      "speaker": "Doctor",
      "text": "Your trach culture came back."
    },
    {
      "turn_number": 33,
      "time": "2166-10-04 14:02:00",
      "speaker": "Patient",
      "text": "Is it infection?"
    },
    {
      "turn_number": 34,
      "time": "2166-10-04 14:04:00",
      "speaker": "Doctor",
      "text": "It grew Pseudomonas, but in moderate amounts and mixed with normal flora. Since you have a trach, that bacteria can live there without causing infection. ENT doesn’t think it needs treatment."
    },
    {
      "turn_number": 35,
      "time": "2166-10-04 14:06:00",
      "speaker": "Patient",
      "text": "So it’s just sitting there?"
    },
    {
      "turn_number": 36,
      "time": "2166-10-04 14:08:00",
      "speaker": "Doctor",
      "text": "Exactly. It’s common in patients with tracheostomies. We only treat it if you’re actively sick, which you’re not."
    },
    {
      "turn_number": 37,
      "time": "2166-10-05 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’d like to discharge you today."
    },
    {
      "turn_number": 38,
      "time": "2166-10-05 10:02:00",
      "speaker": "Patient",
      "text": "Great. What meds will I go home with?"
    },
    {
      "turn_number": 39,
      "time": "2166-10-05 10:04:00",
      "speaker": "Doctor",
      "text": "Same as before, plus a new prescription for hydromorphone for severe pain—just 7 pills, to use only if needed. Keep taking the oxycodone, ibuprofen, and gabapentin as needed."
    },
    {
      "turn_number": 40,
      "time": "2166-10-05 10:06:00",
      "speaker": "Patient",
      "text": "And my breathing treatments?"
    },
    {
      "turn_number": 41,
      "time": "2166-10-05 10:08:00",
      "speaker": "Doctor",
      "text": "Yes, continue the albuterol and saline nebulizers every six hours. Also keep taking fluoxetine, loratadine, and your birth control as usual."
    },
    {
      "turn_number": 42,
      "time": "2166-10-05 10:10:00",
      "speaker": "Patient",
      "text": "When should I follow up?"
    },
    {
      "turn_number": 43,
      "time": "2166-10-05 10:12:00",
      "speaker": "Doctor",
      "text": "See your ENT in a few weeks. Speech therapy will call to schedule your barium swallow. And check in with your PCP to adjust your pain meds if needed."
    },
    {
      "turn_number": 44,
      "time": "2166-10-05 10:14:00",
      "speaker": "Patient",
      "text": "Got it. I feel much better than when I came in."
    },
    {
      "turn_number": 45,
      "time": "2166-10-05 10:16:00",
      "speaker": "Doctor",
      "text": "That’s the goal. Keep up with fluids, soft foods, and rest. Call your doctor if the pain worsens or you develop a fever."
    },
    {
      "turn_number": 46,
      "time": "2166-10-05 10:18:00",
      "speaker": "Patient",
      "text": "Will do. Thanks for explaining everything."
    },
    {
      "turn_number": 47,
      "time": "2166-10-05 10:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll get your discharge papers ready. You should be able to go home in a couple of hours."
    },
    {
      "turn_number": 48,
      "time": "2166-10-05 12:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave. Any dizziness?"
    },
    {
      "turn_number": 49,
      "time": "2166-10-05 12:02:00",
      "speaker": "Patient",
      "text": "No, I feel steady. Ate toast this morning with no problem."
    },
    {
      "turn_number": 50,
      "time": "2166-10-05 12:04:00",
      "speaker": "Doctor",
      "text": "Excellent. Lungs are clear, and you’re walking fine. You’re cleared to go home."
    },
    {
      "turn_number": 51,
      "time": "2166-10-05 12:06:00",
      "speaker": "Patient",
      "text": "Thanks again. I’ll follow up with all my doctors."
    },
    {
      "turn_number": 52,
      "time": "2166-10-05 12:08:00",
      "speaker": "Doctor",
      "text": "Take care. Feel better soon."
    }
  ],
  "summary": {
    "admission_start": "2166-10-03 15:48:00",
    "admission_end": "2166-10-05 18:39:00",
    "summary_paragraph": "A woman with a history of tracheobronchomalacia, tracheostomy, and multiple airway reconstructions was admitted for cough with green sputum, throat pain, and chills. She had decreased oral intake due to odynophagia, leading to mild dizziness from hypovolemia, which improved with IV fluids. Evaluation included a chest X-ray showing no acute process and a fiberoptic exam revealing no tracheitis. Symptoms were attributed to viral URI or bronchotracheitis, and antibiotics were avoided. Pain was managed with oral medications including oxycodone, ibuprofen, and gabapentin, with hydromorphone added for severe pain. Speech and swallow therapy assessed her at baseline and recommended dietary modifications and an outpatient barium swallow. A tracheal aspirate grew Pseudomonas aeruginosa, but it was deemed colonizing rather than infectious. She stabilized, tolerated oral intake, and was discharged home with follow-up plans with ENT, speech therapy, and her PCP.",
    "problems": [
      "Hypovolemia",
      "Tracheostomy status",
      "Congenital tracheomalacia",
      "Other congenital malformations of trachea",
      "Gastro-esophageal reflux disease without esophagitis",
      "Major depressive disorder, single episode, unspecified",
      "Anemia, unspecified",
      "Acute upper respiratory infection, unspecified"
    ]
  }
}
